import {bff} from '@smart/feature-app/node';
import {z} from 'zod';
import {fetchEcomEndpoints} from '../fetch-ecom-endpoints';
import {logger} from '../utils/logger';
import {pcpReserveStock} from '../utils/pcp-reserve-stock';

export const handler = bff(
  async ({
    adb,
    user,
    baseSiteId,
    envName,
    language,
    preview = false,
    rotatingVerifySecret,
    queryParams: {vinNumber, salesChannel},
  }) => {
    if (!user) {
      logger.info(
        `Returning empty cart as we dont have a cart for the anonymous user`,
      );
      return createEmptyCartResponse();
    }
    const userId = user?.userId;
    const ecomConfiguration = await fetchEcomEndpoints({
      envName,
      preview,
      rotatingVerifySecret,
    });
    const purchasedCarsList = await pcpReserveStock({
      language,
      baseSiteId,
      configuration: ecomConfiguration.ecom,
      userId,
      vinNumber,
      salesChannel,
      customerId: adb?.customerUserId,
    });
    return {
      statusCode: 200,
      headers: {
        'Content-Type': `application/json`,
        'Cache-Control': `private, no-store`,
      },
      body: JSON.stringify(purchasedCarsList),
    };
  },
  {
    auth: false,
    schema: {
      queryParams: z.object({
        vinNumber: z.string(),
        salesChannel: z.string(),
      }),
    },
    logger,
    fetchEndpoints: false,
  },
);

function createEmptyCartResponse() {
  return {
    statusCode: 200,
    headers: {
      'Content-Type': `application/json`,
      'Cache-Control': `private, no-store`,
    },
    body: JSON.stringify([]),
  };
}

