import type {Endpoint} from '@smart/endpoint-directory';
import type {UpdatePCPReserveStockModel} from '../update-pcp-reserve-stock/create-reserve-stock-update-model';
import {logger} from './logger';

export async function pcpReserveStock({
  language,
  baseSiteId,
  configuration,
  vinNumber,
  userId,
  salesChannel,
  customerId,
}: {
  language: string;
  baseSiteId: string;
  configuration: Endpoint;
  vinNumber: string;
  userId: string;
  salesChannel: string;
  customerId?: string;
}) {
  const {origin, pathname, authorizationHeaders} = configuration;
  const basePath = `${origin}${pathname}`;
  const headers = new Headers(authorizationHeaders);
  if (customerId) {
    headers.append(`customerId`, customerId);
  }
  headers.append(`Content-Type`, `application/json`);
  if (!authorizationHeaders) {
    logger.error({
      message: `Authorization headers are missing while geting Smart cars`,
    });
    throw new Error(
      `Authorization headers are missing while geting Smart cars`,
    );
  }
  logger.info({vinNumber, userId}, `saveSmartCarToCart: start`);

  const response = await fetch(
    `${basePath}/${baseSiteId}/users/${userId}/carts/current/saveSmartCarToCart?lang=${language}&salesChannel=${salesChannel.toUpperCase()}&vinNumber=${vinNumber}`,
    {
      method: `POST`,
      headers,
    },
  );
  return (await response.json()) as UpdatePCPReserveStockModel;
}

